const searchItems = ($input.first().json.items || []).filter(it => it.id && it.id.videoId);

const videoIds = searchItems.map(it => it.id.videoId);

if (videoIds.length === 0) {
  throw new Error('No videoId values found in YouTube search.list response — cannot proceed to videos.list.');
}

return [{
  json: {
    videoIds: videoIds.join(','),
    searchItems
  }
}];

let existingText = '';
try {
  existingText = $('Extract From File').first()?.json?.data || '';
} catch (e) {
  throw new Error(`Failed to read existing storage: ${e.message}`);
}

const existingUrls = new Set(
  existingText.split('\n').filter(Boolean).map(line => {
    try { return JSON.parse(line).source_url; } catch { return null; }
  }).filter(Boolean)
);

const PLACEHOLDER = 'Unclassified — pending AI extraction';

let searchItems = [];
try {
  searchItems = $('Build Video ID List').first().json.searchItems || [];
} catch (e) {
  throw new Error(`Failed to read search items: ${e.message}`);
}

const statsItems = $input.first().json.items || [];
const statsById = new Map(statsItems.map(v => [v.id, v.statistics || {}]));

const normalized = searchItems.map((item) => {
  const videoId = item.id.videoId;
  const snippet = item.snippet || {};
  const stats = statsById.get(videoId) || {};
  const sourceUrl = `https://www.youtube.com/watch?v=${videoId}`;
  const title = snippet.title || '(untitled)';
  const description = snippet.description || '';
  const rawText = description ? `${title} — ${description}` : title;
  const viewCount = Number(stats.viewCount ?? 0);
  const likeCount = Number(stats.likeCount ?? 0);
  const commentCount = Number(stats.commentCount ?? 0);

  return {
    signal_id: `yt-${videoId}`,
    source_type: 'public_api',
    source_name: 'YouTube (Data API v3)',
    source_url: sourceUrl,
    signal_date: snippet.publishedAt || null,
    market: PLACEHOLDER,
    opportunity_category: PLACEHOLDER,
    opportunity_title: title,
    problem: rawText,
    target_customer: PLACEHOLDER,
    demand_signal: rawText,
    proposed_solution: PLACEHOLDER,
    monetization_model: PLACEHOLDER,
    delivery_method: PLACEHOLDER,
    geography: PLACEHOLDER,
    evidence_notes: `Raw signal ingested from YouTube Data API v3 (search.list + videos.list). Video ID ${videoId}, channel "${snippet.channelTitle || 'unknown'}", ${viewCount} views, ${likeCount} likes, ${commentCount} comments. Not yet human-reviewed.`,
    channel_title: snippet.channelTitle || null,
    video_id: videoId,
    view_count: viewCount,
    like_count: likeCount,
    comment_count: commentCount,
    _dedupe_url: sourceUrl
  };
});

const fresh = normalized.filter((rec) => !existingUrls.has(rec._dedupe_url));

return fresh.map((rec) => {
  const { _dedupe_url, ...clean } = rec;
  return { json: clean };
});
